import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

import AdminLayout from './layouts/AdminLayout';

import Clients from './features/users/pages/Clients';
import Bidders from './features/users/pages/Bidders';
import UserAnalytics from './features/users/pages/UserAnalytics';

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        {/* Redirect root */}
        <Route
          path="/"
          element={<Navigate to="/dashboard" replace />}
        />

        {/* Dashboard */}
        <Route
          path="/dashboard"
          element={
            <AdminLayout>
              <div>Dashboard Page</div>
            </AdminLayout>
          }
        />

        {/* Redirect /users */}
        <Route
          path="/users"
          element={<Navigate to="/users/clients" replace />}
        />

        {/* User Analytics */}
        <Route
          path="/users/analytics"
          element={
            <AdminLayout>
              <UserAnalytics />
            </AdminLayout>
          }
        />

        {/* Clients */}
        <Route
          path="/users/clients"
          element={
            <AdminLayout>
              <Clients />
            </AdminLayout>
          }
        />

        {/* Bidders */}
        <Route
          path="/users/bidders"
          element={
            <AdminLayout>
              <Bidders />
            </AdminLayout>
          }
        />

        {/* Jobs */}
        <Route
          path="/jobs"
          element={
            <AdminLayout>
              <div>Job Management</div>
            </AdminLayout>
          }
        />
      </Routes>
    </BrowserRouter>
  );
}
